const e={knownGoodPack:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Erstelle einen Snapshot der funktionierenden Konfiguration deines Druckers als Pack, das du nach einer fehlerhaften Änderung wiederherstellen kannst."}},cancel:{t:0,b:{t:2,i:[{t:3}],s:"Abbrechen"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Noch keine Packs. Erstelle eines, solange dein Drucker so konfiguriert ist, wie es dir gefällt."}},files:{t:0,b:{t:2,i:[{t:4,k:"n"},{t:3,v:" Konfigurationsdateien"}]}},create:{label:{t:0,b:{t:2,i:[{t:3}],s:"Neues Pack"}},placeholder:{t:0,b:{t:2,i:[{t:3}],s:"z. B. Funktionierender SV08 - vor dem Tuning"}},button:{t:0,b:{t:2,i:[{t:3}],s:"Pack erstellen"}}},restore:{button:{t:0,b:{t:2,i:[{t:3}],s:"Wiederherstellen"}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Aktuelle Konfiguration mit diesem Pack überschreiben?"}},note:{t:0,b:{t:2,i:[{t:3}],s:"Beim Wiederherstellen werden deine Konfigurationsdateien überschrieben; starte Klipper danach neu, um die Änderungen zu übernehmen."}},restored:{t:0,b:{t:2,i:[{t:4,k:"count"},{t:3,v:" Konfigurationsdateien wiederhergestellt - Klipper neu starten, um sie zu übernehmen"}]}},busy:{t:0,b:{t:2,i:[{t:3}],s:"Drucker ist beschäftigt - Wiederherstellen jetzt nicht möglich"}},not_found:{t:0,b:{t:2,i:[{t:3}],s:"Pack-Dateien fehlen"}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Dieses Pack enthält keine Dateien"}},moonraker_error:{t:0,b:{t:2,i:[{t:3,v:"Wiederherstellen fehlgeschlagen: "},{t:4,k:"error"}]}}},delete:{button:{t:0,b:{t:2,i:[{t:3}],s:"Löschen"}},confirm:{t:0,b:{t:2,i:[{t:3}],s:"Pack löschen"}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Anleitung"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Anleitung zu Known-Good-Packs"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Schließen"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"Was ist ein Known-Good-Pack?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Ein Snapshot aller Konfigurationsdateien des Druckers (printer.cfg und die eingebundenen Dateien), gespeichert als benanntes Pack. Wenn dein Drucker gut druckt, erstelle ein Pack, damit du zurückwechseln kannst, falls eine spätere Änderung etwas beschädigt."}}},restore:{title:{t:0,b:{t:2,i:[{t:3}],s:"Ein Pack wiederherstellen"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Beim Wiederherstellen werden die Dateien des Packs über deine aktuelle Konfiguration geschrieben. Es wird abgelehnt, solange der Drucker beschäftigt ist, und du musst Klipper danach neu starten, damit die wiederhergestellte Konfiguration wirksam wird."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossar"}}}},glossary:{configPack:{term:{t:0,b:{t:2,i:[{t:3}],s:"Konfigurations-Pack"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Ein gespeichertes Bündel aller Konfigurationsdateien deines Druckers zu einem bestimmten Zeitpunkt."}}},restorePoint:{term:{t:0,b:{t:2,i:[{t:3}],s:"Wiederherstellungspunkt"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Ein bekannt guter Zustand, zu dem du zurückkehren kannst - hier ein Pack, das erstellt wurde, während der Drucker funktionierte."}}}}}}};export{e as default};
